<?php if (!defined('BASEPATH')) exit('No direct script access allowed');class mpackingcodemodel extends CI_Model {    function fnGetPackingCodeInfo($VarPackingCode = '', $VarStatus = '', $VarId = '', $VarCompanyId = '') {        $this->db->select('id,packingname,updatedby,status,datecreated,dateupdated'); // Select field        $this->db->from(KN_MASTER_PACKING_CODE);        // if ($VarStatus <> '') {        //     $this->db->where_in('status', array($VarStatus));        // } else {        //     $this->db->where_in('status', array(1, 2));        // }        if ($VarId <> '') {            $ArrWhere['id'] = $VarId;        }        if ($VarPackingCode <> '') {            $ArrWhere['packingname'] = trim($VarPackingCode);        }        if ($VarCompanyId <> '') {            $ArrWhere['companyid'] = $VarCompanyId;        }        if (@count($ArrWhere) >= 1) {            $this->db->where($ArrWhere);        }        $ArrResultList = $this->db->get()->result_array();        return $ArrResultList;    }    function fnCheckPackingCode($VarPackingCode = '', $VarId = '', $VarCompanyId = '') {        $this->db->from(KN_MASTER_PACKING_CODE);       // $ArrWhere = array('status' => "1");        if ($VarId <> '') {            $this->db->where_not_in('id', array($VarId));        }        if ($VarPackingCode <> '') {            $ArrWhere['packingname'] = trim($VarPackingCode);        }        if ($VarCompanyId <> '') {            $ArrWhere['companyid'] = $VarCompanyId;        }        return $this->db->where($ArrWhere)->count_all_results();    }    function savePackingCodeInfo($ArrUpdateData) {        $VarId = $ArrUpdateData['id'];        if ($VarId == "") {            $ArrCheckExist = $this->fnGetPackingCodeInfo($ArrUpdateData['packingname'], 1, '', $ArrUpdateData['companyid']);            if (empty($ArrCheckExist)) {                unset($ArrUpdateData['id']);                $this->db->insert(KN_MASTER_PACKING_CODE, $ArrUpdateData);                $VarId = $this->db->insert_id();                $ArrResult['errcode'] = 1;                $ArrResult['msg'] = '';                $ArrResult['id'] = $VarId;                $ArrResult['eid'] = urlencode(base64_encode($VarId));            } else {                $ArrResult['errcode'] = -1;                $ArrResult['msg'] = "This packing code already exists";            }        } else {            $ArrCheckExist = $this->fnCheckPackingCode($ArrUpdateData['packingname'], $VarId,$ArrUpdateData['companyid']);            if (empty($ArrCheckExist)) {                if ($this->db->update(KN_MASTER_PACKING_CODE, $ArrUpdateData, array('id' => $VarId))) {                    $ArrResult['errcode'] = 1;                    $ArrResult['msg'] = '';                    $ArrResult['id'] = $VarId;                    $ArrResult['eid'] = urlencode(base64_encode($VarId));                } else {                    $ArrResult['errcode'] = -1;                    $ArrResult['msg'] = 'Invalid Data';                }            } else {                $ArrResult['errcode'] = -1;                $ArrResult['msg'] = "This packing code already exists";            }        }        return $ArrResult;    }    function fnCountPackingCode($VarPackingCode = '', $VarStatus = '') {        $ArrUserLoggedInfo = fnGetUserLoggedInfo('1');        $ArrWhere = array();        if ($VarPackingCode <> '') {            $ArrWhere[] = "pn.packingname like '%" . $VarPackingCode . "%'";        }        if ($VarStatus <> '') {            $ArrWhere[] = "pn.status=" . $VarStatus;        } else {            $ArrWhere[] = "pn.status in(1,2)";        }        $VarWhere = '';        if (@$ArrWhere[0] <> '') {            $VarWhere = implode(" and ", $ArrWhere) . " AND pn.companyid = " . $ArrUserLoggedInfo['companyid'];        }        $VarSqlPackingCode = "SELECT count(1) as trec  FROM " . KN_MASTER_PACKING_CODE . " AS pn LEFT JOIN " . KN_USERS . " AS u ON pn.updatedby = u.id WHERE " . $VarWhere;        $ObjRows = $this->db->query($VarSqlPackingCode)->row();        return $ObjRows->trec;    }    function fnListPackingCode($VarPackingCode = '', $VarStatus = '', $VarLimit = 10, $offset = 0, $VarSortBy, $VarSortOrder) {        $ArrUserLoggedInfo = fnGetUserLoggedInfo('1');        $VarSortOrder = ($VarSortOrder == 'desc') ? 'desc' : 'asc';        $VarSortCols = array('pn.packingname', 'pn.status', 'u.contactname', 'pn.dateupdated');        $VarSortBy = (in_array($VarSortBy, $VarSortCols)) ? $VarSortBy : 'pn.dateupdated';        $VarLimitInfo = $VarLimit;        if ($offset >= 1) {            $VarLimitInfo = $offset . "," . $VarLimit;        }        $ArrWhere = array();        if ($VarPackingCode <> '') {            $ArrWhere[] = "pn.packingname like '%" . $VarPackingCode . "%'";        }        if ($VarStatus <> '') {            $ArrWhere[] = "pn.status=" . $VarStatus;        } else {            $ArrWhere[] = "pn.status in(1,2)";        }        $VarWhere = '';        if (@$ArrWhere[0] <> '') {            $VarWhere = implode(" and ", $ArrWhere) . " AND pn.companyid = " . $ArrUserLoggedInfo['companyid'];        }        // removed this line in . " limit " . $VarLimitInfo  below query        $VarSqlPackingCode = "SELECT pn.id,pn.packingname,u.contactname,pn.datecreated,pn.dateupdated,pn.status FROM " . KN_MASTER_PACKING_CODE . " AS pn LEFT JOIN " . KN_USERS . " AS u ON pn.updatedby = u.id WHERE " . $VarWhere . " order by " . $VarSortBy . " " . $VarSortOrder;        $ObjResult = $this->db->query($VarSqlPackingCode);        return $ObjResult;    }    function fnChangeComStat($checkboxids, $optvalue) {        $Arrids = json_decode($checkboxids, true);        $this->db->where_in('id', $Arrids);        if ($this->db->update(KN_MASTER_PACKING_CODE, array('status' => $optvalue))) {            return true;        }        return false;    }}